1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	/**
59	 * A fractional amount is always rounded in the MHPCO's favour, once, at the end
60	 * of the calculation it concludes. Which direction that is depends on who pays:
61	 * the customer pays a premium, so it rounds up; the MHPCO pays a claim, so it
62	 * rounds down. Intermediate amounts stay fractional.
63	 */
64	const roundPremiumInMHPCOsFavour = Math.ceil;
65	const roundPayoutInMHPCOsFavour = Math.floor;
66	
67	const BASE_PREMIUMS: Record<string, number> = {
68	  sword: 100,
69	  amulet: 60,
70	  staff: 80,
71	  potion: 40,
72	  rune: 25,
73	  moonstone: 25,
74	};
75	
76	const ALIKE_ITEMS_BLOCK = { size: 3, basePremium: 60 };
77	
78	const basePremiumForItemType = (type: string, count: number): number =>
79	  count === ALIKE_ITEMS_BLOCK.size
80	    ? ALIKE_ITEMS_BLOCK.basePremium
81	    : count * BASE_PREMIUMS[type];
82	
83	const countByType = (items: Item[]): Map<string, number> =>
84	  items.reduce(
85	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
86	    new Map<string, number>(),
87	  );
88	
89	const policyBasePremium = (items: Item[]): number =>
90	  [...countByType(items)].reduce(
91	    (total, [type, count]) => total + basePremiumForItemType(type, count),
92	    0,
93	  );
94	
95	const CURSE_SURCHARGE_RATE = 0.5;
96	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
97	const HIGH_ENCHANTMENT_LEVEL = 5;
98	
99	const isHighlyEnchanted = (item: Item): boolean =>
100	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
101	
102	interface RiskFactor {
103	  applies: (item: Item) => boolean;
104	  rate: number;
105	}
106	
107	const RISK_FACTORS: RiskFactor[] = [
108	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
109	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
110	];
111	
112	const itemRiskSurcharge = (item: Item): number =>
113	  RISK_FACTORS.reduce(
114	    (total, { applies, rate }) =>
115	      applies(item) ? total + BASE_PREMIUMS[item.type] * rate : total,
116	    0,
117	  );
118	
119	const totalRiskSurcharges = (items: Item[]): number =>
120	  items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
121	
122	const LOYALTY_DISCOUNT_RATE = -0.2;
123	const LOYALTY_YEARS = 2;
124	
125	const isLoyal = (customer: Customer): boolean =>
126	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
127	
128	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
129	
130	/** A quote in the context of the customer's history with the MHPCO. */
131	interface Contract {
132	  customer: Customer;
133	  /** Zero-based ordinal of this quote among the customer's quotes. */
134	  ordinal: number;
135	}
136	
137	const isFollowUpContract = (contract: Contract): boolean =>
138	  contract.ordinal > 0;
139	
140	/**
141	 * Policy-wide modifiers are charged on the policy base premium, unlike the
142	 * item-specific RISK_FACTORS which are charged on each affected item's own
143	 * base premium. Rates are signed: negative is a discount.
144	 */
145	interface PolicyFactor {
146	  applies: (contract: Contract) => boolean;
147	  rate: number;
148	}
149	
150	const POLICY_FACTORS: PolicyFactor[] = [
151	  {
152	    applies: ({ customer }) => isLoyal(customer),
153	    rate: LOYALTY_DISCOUNT_RATE,
154	  },
155	  { applies: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
156	  {
157	    applies: isFollowUpContract,
158	    rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
159	  },
160	];
161	
162	const totalPolicyAdjustments = (
163	  policyBase: number,
164	  contract: Contract,
165	): number =>
166	  POLICY_FACTORS.reduce(
167	    (total, { applies, rate }) =>
168	      applies(contract) ? total + policyBase * rate : total,
169	    0,
170	  );
171	
172	const quotePremium = (items: Item[], contract: Contract): number => {
173	  const policyBase = policyBasePremium(items);
174	  return roundPremiumInMHPCOsFavour(
175	    policyBase +
176	      totalRiskSurcharges(items) +
177	      totalPolicyAdjustments(policyBase, contract) +
178	      PROCESSING_FEE,
179	  );
180	};
181	
182	const INSURANCE_VALUES: Record<string, number> = {
183	  sword: 1000,
184	  amulet: 600,
185	  staff: 800,
186	  potion: 400,
187	  rune: 250,
188	  moonstone: 250,
189	};
190	
191	const DEDUCTIBLE_PER_DAMAGE = 100;
192	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
193	
194	const insuranceSum = (items: Item[]): number =>
195	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
196	
197	const payoutCap = (items: Item[]): number =>
198	  insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
199	
200	/**
201	 * Distinct from the premium side's HIGH_ENCHANTMENT_LEVEL of 5: the payout
202	 * rule and the surcharge rule share a shape but not a threshold.
203	 */
204	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
205	const HALF_REIMBURSEMENT_RATE = 0.5;
206	const FULL_REIMBURSEMENT_RATE = 1;
207	
208	/**
209	 * The share of a damage amount the MHPCO reimburses, before the deductible.
210	 * Damage to a heavily enchanted item is reimbursed at half.
211	 */
212	const reimbursementRate = (item: Item): number =>
213	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
214	    ? HALF_REIMBURSEMENT_RATE
215	    : FULL_REIMBURSEMENT_RATE;
216	
217	const damagePayout = (damage: Damage, policyItems: Item[]): number => {
218	  const damagedItem = policyItems.find(
219	    (item) => item.type === damage.itemType,
220	  ) as Item;
221	  return damage.amount * reimbursementRate(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
222	};
223	
224	const claimResult = (
225	  step: ClaimStep,
226	  policyItems: Item[],
227	  capAlreadyUsed: number,
228	): ClaimResult => {
229	  const claimed = roundPayoutInMHPCOsFavour(
230	    step.incident.damages.reduce(
231	      (total, damage) => total + damagePayout(damage, policyItems),
232	      0,
233	    ),
234	  );
235	  // The cap covers the policy's whole lifetime, so a claim can only draw on
236	  // what earlier claims against the same policy have left.
237	  const capLeft = payoutCap(policyItems) - capAlreadyUsed;
238	  const payout = Math.min(claimed, capLeft);
239	  return { payout, remainingCap: capLeft - payout };
240	};
241	
242	/**
243	 * The items covered by the policy a claim is filed against. A claim's `policy`
244	 * is the index of the quote step that established the policy.
245	 *
246	 * Assumes that step is in fact a quote; no test yet covers a claim pointing at
247	 * a non-quote step, so the assumption is asserted rather than checked.
248	 */
249	const policyItemsFor = (steps: Step[], claim: ClaimStep): Item[] =>
250	  (steps[claim.policy] as QuoteStep).items;
251	
252	const runStep = (
253	  step: Step,
254	  contract: Contract,
255	  steps: Step[],
256	  capUsedByPolicy: Map<number, number>,
257	): StepResult => {
258	  if (step.op === "claim") {
259	    const result = claimResult(
260	      step,
261	      policyItemsFor(steps, step),
262	      capUsedByPolicy.get(step.policy) ?? 0,
263	    );
264	    capUsedByPolicy.set(
265	      step.policy,
266	      (capUsedByPolicy.get(step.policy) ?? 0) + result.payout,
267	    );
268	    return result;
269	  }
270	  return { premium: quotePremium(step.items, contract) };
271	};
272	
273	/** The contract ordinal of a step: how many quotes precede it. */
274	const contractOrdinalOf = (steps: Step[], index: number): number =>
275	  steps.slice(0, index).filter((step) => step.op === "quote").length;
276	
277	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
278	  const capUsedByPolicy = new Map<number, number>();
279	  return {
280	    results: steps.map((step, index) =>
281	      runStep(
282	        step,
283	        { customer, ordinal: contractOrdinalOf(steps, index) },
284	        steps,
285	        capUsedByPolicy,
286	      ),
287	    ),
288	  };
289	};
