const runStep = (
  step: Step,
  contract: Contract,
  steps: Step[],
  capUsedByPolicy: Map<number, number>,
): StepResult => {
  if (step.op === "claim") {
    const result = claimResult(
      step,
      policyItemsFor(steps, step),
      capUsedByPolicy.get(step.policy) ?? 0,
    );
    capUsedByPolicy.set(
      step.policy,
      (capUsedByPolicy.get(step.policy) ?? 0) + result.payout,
    );
    return result;
  }
  return { premium: quotePremium(step.items, contract) };
};

/** The contract ordinal of a step: how many quotes precede it. */
const contractOrdinalOf = (steps: Step[], index: number): number =>
  steps.slice(0, index).filter((step) => step.op === "quote").length;

export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
  const capUsedByPolicy = new Map<number, number>();
  return {
    results: steps.map((step, index) =>
      runStep(
        step,
        { customer, ordinal: contractOrdinalOf(steps, index) },
        steps,
        capUsedByPolicy,
      ),
    ),
  };
};

